pe":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(304,224)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"21,382","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"5,350","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(277,492)","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Corrections","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"552,283","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(143,717)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"105,527","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"514,093","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"31 December","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"41,972,216","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(21,824,655)","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"(2,242,412)","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"17,905,149","type":"text","marks":[{"type":"bold"}]}]}]}]}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Additions = 183,123 producing assets + 231,940 E&E wells + 3,531,179 development wells = 3,946,242","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Reinvestment ratio = 3,946,242 / 2,187,085 = 1.80 times","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Accumulated DD&A and impairment / cost = (21,824,655 + 2,242,412) / 41,972,216 = 57.3%","type":"text"}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Three presentation points need a careful reader. The \"corrections\" column adds 514,093 net and is not explained in the note. The English text of the impairment paragraph gives the 2024 loss as US$257,554, while the Indonesian text and the table give 220,899 (Daftar 5/110, PDF p. 127), and the Indonesian text is the original. And the decommissioning movement in Note 29 prints the 2024 revision as 78,620 without brackets, although the balance only foots if it is a reduction: 3,784,917 − 78,620 + 119,925 = 3,826,222.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Exploration expense.","type":"text","marks":[{"type":"bold"}]},{"text":" Note 36 shows what successful efforts sends straight to profit or loss (Daftar 5/149, PDF p. 166).","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2024","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2023","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Dry holes","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"156,746","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"100,703","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Geological and geophysical","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"126,786","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"77,408","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Administration and exploration","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"123,932","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"68,407","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Others","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"57,958","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"20,055","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Exploration expenses","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"465,422","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"266,573","type":"text","marks":[{"type":"bold"}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Dry holes are exploration wells written off for finding no proved reserves, like well B in section 2; geological and geophysical costs are seismic and studies. Administration and exploration is presumably the overhead of the exploration function, which PHE does not break down. The line rose 198,849, or 74.6 percent, and dry holes 56,043 of it. Under full cost the dry holes and geological and geophysical costs, 283,532 or 60.9 percent of the line, would sit in the asset, and so would overhead directly tied to exploration, so this is the line where the two methods' profits part.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"DD&A.","type":"text","marks":[{"type":"bold"}]},{"text":" The face line is wider than this asset's depletion (Daftar 2/1, PDF p. 14). Note 46 splits it by segment, exploration and production 2,416,986, services 94,292 and elimination −68,278 (Daftar 5/220, PDF p. 237), but not by asset, so the build below is this page's.","type":"text"}]},{"type":"table","content":[{"type":"tableRow","content":[{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null}}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2024","type":"text"}]}]},{"type":"tableHeader","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2023","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Oil and gas properties (Note 17)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2,187,085","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2,570,262","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Fixed assets (Note 12, Daftar 5/100–5/101)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"74,311","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"68,401","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Investments in oil and gas blocks (Note 16a, Daftar 5/107)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"–","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"81,381","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Right-of-use assets (Note 18) and intangibles (Note 13)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"120,322","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"134,542","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Not identified (see Least-confident)","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"61,282","type":"text"}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2,267","type":"text"}]}]}]},{"type":"tableRow","content":[{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Depreciation, depletion and amortisation","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2,443,000","type":"text","marks":[{"type":"bold"}]}]}]},{"type":"tableCell","attrs":{"align":null,"colspan":1,"rowspan":1,"colwidth":null},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"2,856,853","type":"text","marks":[{"type":"bold"}]}]}]}]}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The line fell 413,853, or 14.5 percent. Depletion of wells fell 383,467 (1,882,700 to 1,499,233) while the cost of producing assets grew. The Malaysian and Iraqi block investments, amortised by 81,381 in 2023, show no 2024 amortisation. Under units of production the charge falls when output falls, when reserves rise, or when the cost to deplete shrinks, and the 2023 impairment of 707,087 cut that cost before 2024 began. The statements give neither volumes nor reserves, so the three causes cannot be separated.","type":"text"}]},{"type":"blockquote","attrs":{"variant":"quote"},"content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"DD&A / opening cost of producing assets = 2,187,085 / 34,452,668 = 6.3% (2023: 2,570,262 / 30,409,868 = 8.5%)","type":"text"}]}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"9. Upstream note: who owns the wells","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Under a cost-recovery PSC, \"materials, supplies and equipment acquired by the PSC Contractors … belongs to the Government\", while the contractor may use them until SKK Migas, the upstream regulator, approves them as surplus or abandoned (Note 2a(vii), Daftar 5/11, PDF p. 28). PHE still carries the wells and facilities. An asset under the Conceptual Framework is a resource the entity controls, control is the present ability to direct its use and obtain its benefits, and the 1989 Framework already said that ownership is not essential. A plausible reading is that the contractor directs the use of the wells and recovers their cost, though PHE does not explain why it recognises them.","type":"text"}]},{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Annual cost recovery under the PSC comprises the year's non-capital costs, depreciation of capital costs, and earlier unrecovered costs (Note 2a(iii), Daftar 5/10, PDF p. 27). Book depletion and PSC depreciation follow different schedules, and the gap between them is a temporary difference for deferred tax. Under gross split contracts there is no cost recovery, and the old PSC assets, now owned by the Directorate General of State Assets (DJKN), are used under a lease scheme (Note 2b, Daftar 5/17, PDF p. 34).","type":"text"}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"10. Related lines","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"fixed-assets-net","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/fixed-assets-net","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the boundary for assets that serve the company generally.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"decommissioning-site-restoration-provision","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/decommissioning-site-restoration-provision","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the liability side of section 5.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"restricted-cash-non-current","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/restricted-cash","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the decommissioning funds held in joint accounts with SKK Migas.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"exploration-expenses","type":"text","marks":[{"type":"code"}]},{"text":", ","type":"text"},{"text":"depreciation-depletion-amortization","type":"text","marks":[{"type":"code"}]},{"text":": the profit or loss lines this asset feeds, covered on this page (section 8).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"impairment-non-financial-assets","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/impairment-non-financial-assets","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the full PSAK 236 test behind section 6.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"advances-prepayments-current","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/advances-prepayments-current","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": cash calls paid to operators before the spending reaches this line.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"inventories-net","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/inventories-net","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": materials issued to development wells.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"deferred-tax-liabilities","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/deferred-tax-assets","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":": the gap between book depletion and PSC recovery.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":3,"textAlign":null},"content":[{"text":"Least-confident assertions","type":"text"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The control argument for carrying government-owned wells is this page's reading; PHE does not give one.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PHE's policy says depletion uses \"proved reserves\" and defines them as developed plus undeveloped; whether PHE adds future development costs to the base is not disclosed, so the FDC treatment shown is the textbook rule and may differ from PHE's practice.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The 3.17 percent \"average discount rate\" is accretion over the opening provision, so only a rough figure. The reading that Note 29's 78,620 is a reduction rests on footing alone; PHE may have omitted a line rather than a bracket.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"The DD&A build in section 8 is this page's. The face cites Notes 12, 16a and 17, which explain 2,261,396 of 2,443,000 in 2024. Note 18's 2024 depreciation column includes a credit of 59,120 on tanks and pipelines, probably a misplaced derecognition or correction; without it right-of-use depreciation is 166,292 and, with intangible amortisation (Note 13, 13,150), the residual is about 2,162, close to 2023's 2,267. As printed, the residual is 61,282. Note 16a shows no 2024 amortisation of the Malaysian blocks, only a derecognition of 63,703.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"How far a full-cost-style E&E policy can defer dry-hole cost under PSAK 106 is this page's reading of paras. 9 and 17; no standard or interpretation found says whether a dry hole may enter a field's development cost on reclassification.","type":"text"}]}]}]},{"type":"heading","attrs":{"level":2,"textAlign":null},"content":[{"text":"References","type":"text"}]},{"type":"orderedList","attrs":{"type":null,"start":1},"content":[{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PT Pertamina Hulu Energi dan Entitas Anak, consolidated financial statements 31 December 2024 (audited, USD thousand): statement of financial position (Daftar 1/1, PDF p. 11); Note 2a(iii) and 2a(vii) (Daftar 5/10–5/11, PDF pp. 27–28); Note 2b (Daftar 5/17, PDF p. 34); Note 3m (Daftar 5/56–5/57, PDF pp. 73–74); Note 3o (Daftar 5/60–5/61, PDF pp. 77–78); Note 3w (Daftar 5/72–5/73, PDF pp. 89–90); Note 3y (Daftar 5/74, PDF p. 91); Note 4b(i) (Daftar 5/78–5/79, PDF pp. 95–96); Note 17 (Daftar 5/109–5/111, PDF pp. 126–128); Note 29 (Daftar 5/145, PDF p. 162, page image checked); Note 36 (Daftar 5/149, PDF p. 166). Profit or loss lines: statement of profit or loss (Daftar 2/1, PDF p. 14); Note 3p (Daftar 5/63, PDF p. 80); Note 12 (Daftar 5/100–5/101, PDF pp. 117–118); Note 13 (Daftar 5/104, PDF p. 121); Note 16a (Daftar 5/107, PDF p. 124); Note 18 (Daftar 5/112, PDF p. 129). VERIFIED (PHE FS 2024, on disk; line figures checked against the PHE FS 2024 data extract).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lecture notes this series follows, \"Inter 1 – Chapter 10 – Acquisition and Disposition of Property, Plant and Equipment\" (Rumpun Akuntansi Keuangan): cost elements, self-constructed assets and overhead, capitalisation of interest (worked on the ","type":"text"},{"text":"fixed-assets-net","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/fixed-assets-net","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":" page), later spending. NOTES.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lecture notes, \"Inter 1 – Chapter 12 – Intangible Assets\": research versus development, impairment of limited-life assets, reversal capped by the no-impairment carrying amount. NOTES. The notes measure recoverable amount by fair value only; corrected here to the higher of fair value less costs of disposal and value in use.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lecture notes, \"Inter 2 – Chapter 13 – Current Liabilities, Provisions and Contingencies\": recognition of provisions and the environmental provision with a matching asset. NOTES. The notes do not cover exploration accounting, depletion or the extractive standards; sections 2, 4 and 7 follow the standards named.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lecture notes, \"Inter 1 – Chapter 2 – Conceptual Framework\" and \"TA – Chapter 7 – Assets\": matching, and control over ownership. NOTES. The TA note quotes the FASB, IASC and AASB asset definitions and names no author for the control point. The 1989 Framework's \"ownership is not essential\" wording VERIFIED (web, IFRS Foundation material quoting the Framework).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Kieso, D. E., Weygandt, J. J. and Warfield, T. D., ","type":"text"},{"text":"Intermediate Accounting, IFRS Edition","type":"text","marks":[{"type":"italic"}]},{"text":" (Wiley), chapters on acquisition and disposition of property, plant and equipment, intangible assets, and current liabilities, provisions and contingencies; the textbook the notes above follow. Edition not checked. STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Godfrey, J., Hodgson, A., Tarca, A., Hamilton, J. and Holmes, S., ","type":"text"},{"text":"Accounting Theory","type":"text","marks":[{"type":"italic"}]},{"text":" (Wiley), the text the TA notes are thought to follow; not cited in the body, because the book is not on disk. NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 106 (IFRS 6), paras. 5, 9, 10, 17–21. VERIFIED (web, IFRS Foundation text of IFRS 6 reproduced at ktkt.uel.edu.vn; faronline.se for paras. 3 and 5).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 216 (IAS 16), paras. 12 and 16(c). VERIFIED (web, ACCA technical article and study materials quoting the paragraphs).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 223 (IAS 23), capitalisation of borrowing costs on qualifying assets (worked on the ","type":"text"},{"text":"fixed-assets-net","type":"text","marks":[{"type":"link","attrs":{"rel":"noopener noreferrer nofollow","href":"/accounting/fsli/fixed-assets-net","class":"text-primary underline cursor-pointer hover:text-primary/80","title":null,"target":"_blank"}}]},{"text":" page). VERIFIED (web, IFRS Interpretations Committee staff papers; secondary summaries).","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 236 (IAS 36), recoverable amount and the capped reversal (para. 117). VERIFIED (web, KPMG and Grant Thornton guidance on reversals; ACCA article). Worked in full in the Impairment of non-financial assets essay.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"ISAK 101 (IFRIC 1), paras. 5 and 8. VERIFIED (web, earlier recheck via faronline.se and BDO excerpts; scope reconfirmed via faronline.se 2026-10-11); the full interpretation was not reopened.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"ISAK 120 (IFRIC 20). Allocation principle VERIFIED (web, IFRS Foundation IFRIC 20 page and IAS Plus summary); ratio-based example STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"PSAK 201 (IAS 1) para. 66; PSAK 208 (IAS 8); PSAK 237 (IAS 37); PSAK 111 (IFRS 11). Numbers and titles VERIFIED (web, IAI, ","type":"text"},{"text":"Perubahan Penomoran PSAK dan ISAK dalam SAK Indonesia","type":"text","marks":[{"type":"italic"}]},{"text":"); content STANDARD — NOT VERIFIED.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"SEC Regulation S-X Rule 4-10 full cost ceiling test. VERIFIED (web, SEC filings by Ultra Petroleum and Anadarko describing the test); rule text not opened, and its tax adjustments are left out of the example.","type":"text"}]}]},{"type":"listItem","content":[{"type":"paragraph","attrs":{"textAlign":null},"content":[{"text":"Lessons salvaged from the independent recheck of the superseded draft (2026-10-09), and the v0.5 recheck (2026-10-11).","type":"text"}]}]}]}]}$j$::jsonb,
       presentation = $p${"deck":"The theory of upstream asset accounting from the first seismic line to the last plugged well, worked through PHE's numbers and set beside the industries with their own rules","genre":null,"author_bio":null,"references":[],"hero_caption":null,"key_takeaways":["Upstream asset accounting answers four questions in order: which finding costs become an asset, what a field costs to develop, how that cost is released as barrels are produced, and whether the cost left will come back. The cost policy settles the first, PSAK 216 the second, units-of-production depletion the third, and the impairment test of PSAK 236 the fourth.","Successful efforts and full cost split the same exploration spending differently. Successful efforts expenses a dry hole at once, while full cost keeps it on the balance sheet and releases it with the successful barrels. Under PSAK 106 full cost survives only inside exploration and evaluation.","The cost of a field includes the present value of the cost to remove it. Decommissioning enters the asset on day one, grows each year as a finance cost, and a change in its estimate adjusts the asset's cost, in most cases leaving profit untouched. PHE carries 17,905,149 of oil and gas properties, net, with 2,242,412 of accumulated impairment against them."],"revision_note":null}$p$::jsonb,
       updated_at = now()
 WHERE id = '607700de-8b2a-4086-bb39-03f553b3dfed';
INSERT INTO public.essay_revisions (essay_id, revision_no, change_type, title, snippet, content_json, status, change_summary, changed_by)
SELECT e.id, coalesce((SELECT max(x.revision_no) FROM public.essay_revisions x WHERE x.essay_id = e.id), 0) + 1, 'rollback',
       e.title, e.snippet, e.content_json, e.status, $s$Restored from the snapshot taken before the lecture-notes removal$s$, null
  FROM public.essays e WHERE e.id = '607700de-8b2a-4086-bb39-03f553b3dfed';

DO $chk$ BEGIN
  IF (SELECT count(*) FROM public.essays WHERE id IN ('d035aea1-7784-4c3c-9da1-d942b016fedc', 'aab4ee41-2d26-4015-85c2-6c81bba23314', '2d6391ad-0b0d-472c-a2d9-1db6ecfc014a', '607700de-8b2a-4086-bb39-03f553b3dfed') AND updated_at = now()) <> 4 THEN
    RAISE EXCEPTION 'Not written: an essay in this part was changed after the snapshot. Nothing in this part was saved.';
  END IF;
END $chk$;
